using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Mbb.Archive.BuildingBlocks.Messaging.RabbitMq;using Mbb.Archive.Modules.Audit.Infrastructure.Persistence;using RabbitMQ.Client;using RabbitMQ.Client.Events;
namespace Mbb.Archive.Modules.Audit.Infrastructure;internal sealed class AuditEventConsumer:BackgroundService{private readonly RabbitMqConnection _rabbit;private readonly IServiceScopeFactory _scopes;private readonly TimeProvider _time;public AuditEventConsumer(RabbitMqConnection r,IServiceScopeFactory s,TimeProvider t){_rabbit=r;_scopes=s;_time=t;}protected override async Task ExecuteAsync(CancellationToken ct){await using var ch=await _rabbit.CreateConsumerChannelAsync(ct);await ch.BasicQosAsync(0,1,false,ct);var c=new AsyncEventingBasicConsumer(ch);c.ReceivedAsync+=async(_,d)=>{try{await Persist(d,ct);await ch.BasicAckAsync(d.DeliveryTag,false,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){throw;}catch{await Task.Delay(2000,ct);await ch.BasicNackAsync(d.DeliveryTag,false,true,ct);}};await ch.BasicConsumeAsync("mbb.archive.audit.events.v1",false,c,ct);await Task.Delay(Timeout.InfiniteTimeSpan,ct);}private async Task Persist(BasicDeliverEventArgs d,CancellationToken ct){var payload=Encoding.UTF8.GetString(d.Body.Span);var messageId=Guid.TryParse(d.BasicProperties.MessageId,out var parsed)?parsed:DeterministicGuid(payload);await using var scope=_scopes.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<AuditDbContext>();if(await db.Entries.AnyAsync(x=>x.MessageId==messageId,ct))return;await using var tx=await db.Database.BeginTransactionAsync(ct);await db.Database.ExecuteSqlRawAsync("SELECT pg_advisory_xact_lock(824601001)",ct);var previous=await db.Entries.OrderByDescending(x=>x.Sequence).Select(x=>new{x.Sequence,x.EntryHash}).FirstOrDefaultAsync(ct);var sequence=(previous?.Sequence??0)+1;var eventName=d.BasicProperties.Type??"unknown";var occurred=DateTimeOffset.FromUnixTimeSeconds(d.BasicProperties.Timestamp.UnixTime);var received=_time.GetUtcNow();var documentId=ExtractDocumentId(payload);var previousHash=previous?.EntryHash??new string('0',64);var hash=Hash(previousHash,messageId,eventName,occurred,payload);db.Entries.Add(new AuditEntry(sequence,messageId,eventName,payload,documentId,occurred,received,previousHash,hash));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}private static string Hash(string previous,Guid id,string name,DateTimeOffset at,string payload)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{previous}|{id:D}|{name}|{at:O}|{payload}"))).ToLowerInvariant();private static Guid? ExtractDocumentId(string payload){try{using var j=JsonDocument.Parse(payload);if(j.RootElement.TryGetProperty("documentId",out var v)&&Guid.TryParse(v.GetString(),out var g))return g;}catch{}return null;}private static Guid DeterministicGuid(string payload)=>new(SHA256.HashData(Encoding.UTF8.GetBytes(payload)).AsSpan(0,16));}
